),
u1 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'أساسيات الاستشعار عن بعد','مبادئ القياس الإشعاعي وتطبيقاته الجوية.',1,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u2 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'أنواع الأقمار الصناعية ومداراتها','المدارات الثابتة والقطبية وخصائص التغطية.',2,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u3 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'القنوات الطيفية وتفسير الصور','القنوات المرئية وتحت الحمراء وبخار الماء.',3,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
