u5 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'التحليل الجوي بالاستشعار عن بعد','دمج منتجات الأقمار والرادار في التحليل.',5,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values
('remote-sensing-principles-in-meteorology','مبادئ الاستشعار عن بعد في الأرصاد الجوية','أسس الاستشعار عن بعد والتفاعل الإشعاعي والتمييز بين القياسات السلبية والفعالة وتطبيقاتها الجوية.','{"blocks":[{"type":"heading","text":"مفهوم الاستشعار عن بعد"},{"type":"text","text":"الاستشعار عن بعد هو الحصول على معلومات عن سطح الأرض أو الغلاف الجوي دون ملامسته مباشرة، من خلال قياس الطاقة الكهرومغناطيسية المنبعثة أو المنعكسة أو المتشتتة. في الأرصاد الجوية يوفر رؤية واسعة ومتكررة للسحب وبخار الماء ودرجات الحرارة وبعض خصائص السطح."},{"type":"heading","text":"مكونات منظومة الاستشعار"},{"type":"list","items":["مصدر للطاقة، مثل الشمس في الأنظمة السلبية أو باعث راداري في الأنظمة الفعالة.","الغلاف الجوي الذي قد يمتص الإشعاع أو يشتته.","الهدف المراد رصده، مثل السحب أو سطح البحر أو اليابسة.","المستشعر الذي يقيس الإشعاع ضمن نطاقات طيفية محددة.","المعالجة والتحقق وتحويل القياسات إلى منتجات قابلة للتفسير."]},{"type":"heading","text":"الاستشعار السلبي والفعال"},{"type":"text","text":"يقيس المستشعر السلبي الإشعاع الطبيعي المنعكس عن الشمس أو المنبعث من الأرض والغلاف الجوي. أما المستشعر الفعال فيرسل طاقة ثم يقيس الإشارة المرتدة، كما في الرادار. تختلف التطبيقات بحسب الطول الموجي وطبيعة الهدف وظروف الرصد."},{"type":"heading","text":"الطيف الكهرومغناطيسي"},{"type":"text","text":"تستخدم الأقمار الجوية نطاقات مرئية وتحت حمراء ونطاقات بخار الماء وغيرها. لكل نطاق حساسية مختلفة للخصائص الجوية؛ فالمرئي يعتمد على الإضاءة الشمسية، بينما يمكن للأشعة تحت الحمراء أن توفر معلومات حرارية ليلاً ونهاراً."},{"type":"heading","text":"التفاعل مع الغلاف الجوي"},{"type":"text","text":"يتأثر الإشعاع بالامتصاص والتشتت والانبعاث. تمتص بعض الغازات أطوالاً موجية محددة، كما تؤثر السحب والهباء الجوي في انتقال الطاقة. تسمى النطاقات التي تسمح بمرور قدر أكبر من الإشعاع بالنوافذ الجوية."},{"type":"heading","text":"الدقة المكانية والطيفية والزمنية"},{"type":"list","items":["المكانية: حجم المنطقة التي تمثلها الخلية أو البكسل.","الطيفية: قدرة المستشعر على تمييز نطاقات أو فروق طيفية دقيقة.","الزمنية: معدل تكرار التصوير للمنطقة نفسها.","الإشعاعية: قدرة النظام على التمييز بين مستويات الإشارة."]},{"type":"heading","text":"المعايرة والتحويل إلى منتجات"},{"type":"text","text":"تبدأ معالجة البيانات عادة بالمعايرة الإشعاعية والهندسية، ثم قد تطبق تصحيحات جوية أو خوارزميات استخراج. تختلف المنتجات بين قياسات قريبة من الإشارة الأصلية ومؤشرات مشتقة مثل درجة حرارة قمم السحب أو تقدير الرطوبة."},{"type":"heading","text":"حدود القياس الفضائي"},{"type":"text","text":"لا تقيس الأقمار كل متغير جوي مباشرة. كثير من المنتجات تقديرات تعتمد خوارزميات وافتراضات، وقد تتأثر بالسحب أو زاوية الرؤية أو سطح الأرض أو حجم البكسل. يجب قراءة وصف المنتج ومجاله وعدم يقينه."},{"type":"heading","text":"تطبيقات الأرصاد"},{"type":"list","items":["تحديد مواقع السحب وأنواعها وتطورها.","متابعة بخار الماء والأنظمة واسعة النطاق.","رصد درجات حرارة قمم السحب وسطح البحر.","تقدير خصائص الهطول والثلوج وفق منتجات متخصصة.","متابعة الغبار والدخان والرماد البركاني."]},{"type":"callout","text":"الصورة الفضائية ليست خريطة مباشرة لكل عناصر الطقس؛ إنها قياس إشعاعي يحتاج إلى تفسير ومعالجة ومعرفة بخصائص القناة."},{"type":"example","text":"مثال: قد تبدو سحابة باردة جداً في قناة تحت حمراء، لكن تحديد احتمال الهطول يتطلب دمج تطورها الرأسي والزمني مع الرادار والبيانات السطحية والنماذج."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يمنح الاستشعار عن بعد تغطية مكانية واسعة، لكن جودة التفسير تعتمد على فهم النطاق الطيفي والدقة والمعالجة والقيود الفيزيائية للمنتج."}]}',450,50,'["شرح مفهوم الاستشعار عن بعد ومكوناته","التمييز بين الاستشعار السلبي والفعال","تفسير حدود القياسات الفضائية وتطبيقاتها الجوية"]','أساسيات الاستشعار عن بعد'),
('geostationary-and-polar-orbiting-weather-satellites','الأقمار الصناعية الثابتة والمدارية القطبية','مقارنة المدارات الجغرافية الثابتة والمدارات القطبية وتغطيتها ودورية الرصد واستخداماتها.','{"blocks":[{"type":"heading","text":"لماذا تستخدم الأرصاد الأقمار الصناعية؟"},{"type":"text","text":"تتيح الأقمار الصناعية مراقبة مناطق واسعة تشمل المحيطات والصحارى والمناطق النائية التي تقل فيها المحطات الأرضية. وتكمل بياناتها قياسات المحطات والرادار والطائرات والمجسات الجوية."},{"type":"heading","text":"المدار الثابت بالنسبة للأرض"},{"type":"text","text":"يدور القمر الجغرافي الثابت في مدار دائري فوق خط الاستواء وبزمن دوران يساوي تقريباً زمن دوران الأرض، فيبدو ثابتاً فوق خط طول محدد. يتيح ذلك تصوير المنطقة نفسها بصورة متكررة ومتابعة تطور السحب والعواصف."},{"type":"heading","text":"مزايا المدار الثابت"},{"type":"list","items":["تكرار زمني مرتفع لمراقبة التطور السريع.","متابعة مستمرة تقريباً لنصف الكرة المرئي من موقع القمر.","ملاءمة مراقبة العواصف الرعدية والأنظمة المتحركة.","إنتاج متتابعات زمنية وصور متحركة لتطور السحب."]},{"type":"heading","text":"قيود المدار الثابت"},{"type":"text","text":"تقل الدقة الهندسية عادة قرب حواف مجال الرؤية بسبب زاوية المشاهدة، ولا يغطي القمر كامل الكرة الأرضية. كما تختلف تفاصيل الرصد بحسب الجهاز والقنوات وجدول المسح."},{"type":"heading","text":"المدار القطبي أو شبه القطبي"},{"type":"text","text":"يمر القمر في مسارات قريبة من القطبين بينما تدور الأرض تحته، فيغطي شرائط متعاقبة من سطح الكوكب. وقد تكون هذه الأقمار على ارتفاع أقل من الأقمار الجغرافية الثابتة، ما يتيح تفاصيل مكانية أدق لبعض المستشعرات."},{"type":"heading","text":"مزايا المدار القطبي"},{"type":"list","items":["تغطية عالمية تدريجية مع تكرار يعتمد على المدار وعدد الأقمار.","إمكان حمل مستشعرات تصوير وقياس رأسي متخصصة.","دعم تحليل الحرارة والرطوبة وبنية الغلاف الجوي.","توفير قياسات تفصيلية تدخل في النماذج العددية."]},{"type":"heading","text":"مقارنة المدارين"},{"type":"text","text":"الثابت مناسب للمتابعة الزمنية السريعة لمنطقة محددة، بينما يوفر القطبي تغطية عالمية متعاقبة وقد يقدم دقة مكانية أو قياسات رأسية متخصصة. لا يعني ذلك أن أحدهما أفضل مطلقاً؛ فالاختيار مرتبط بالسؤال العلمي."},{"type":"heading","text":"المسح والتغطية"},{"type":"text","text":"تحدد زاوية الرؤية وجدول المسح ومجال الجهاز عدد الصور وتواترها. بعض الأقمار تنفذ مسحاً كاملاً، وأخرى تركز على مناطق محددة لمراقبة الظواهر السريعة."},{"type":"heading","text":"دمج بيانات الأقمار"},{"type":"text","text":"تدمج منتجات الأقمار الثابتة والقطبية مع الرصد السطحي والرادار والمجسات الجوية. ينبغي توحيد التوقيت والإسقاط المكاني ومراعاة اختلاف الدقة والخوارزميات قبل المقارنة."},{"type":"heading","text":"اختيار المصدر المناسب"},{"type":"list","items":["تطور عاصفة خلال دقائق: بيانات متكررة من قمر ثابت.","تحليل عالمي أو قياسات رأسية: منتجات أقمار قطبية مناسبة.","مراقبة منطقة قرب حافة مجال الرؤية: راجع زاوية الرصد وجودة الصورة.","تحليل طويل الأمد: تحقق من اتساق السجلات وتغير الأجهزة والخوارزميات."]},{"type":"callout","text":"لا تقارن منتجين فضائيين اعتماداً على اسم القمر فقط؛ افحص المستشعر والقناة والدقة والتوقيت وإصدار المنتج."},{"type":"example","text":"مثال: لمتابعة نمو سحب رعدية فوق منطقة ما، تفيد الصور المتكررة للقمر الثابت. أما دراسة توزيع الحرارة والرطوبة رأسياً فقد تتطلب منتجاً من مستشعر قطبي متخصص."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يكمل المدار الثابت والمدار القطبي أحدهما الآخر؛ الأول يبرز التغير الزمني السريع، والثاني يضيف تغطية عالمية وقياسات تفصيلية بحسب المستشعر."}]}',460,50,'["مقارنة المدار الثابت والمدار القطبي","شرح أثر المدار في التغطية والدقة الزمنية والمكانية","اختيار نوع الرصد الملائم للتطبيق الجوي"]','أنواع الأقمار الصناعية ومداراتها'),
('satellite-spectral-channels-visible-infrared-water-vapor','القنوات الطيفية: المرئية وتحت الحمراء وبخار الماء','قراءة القنوات الفضائية الأساسية وفهم سطوع الصورة والحرارة وامتصاص بخار الماء.','{"blocks":[{"type":"heading","text":"ما القناة الطيفية؟"},{"type":"text","text":"القناة الطيفية نطاق محدد من الأطوال الموجية يقيس فيه المستشعر الإشعاع. تختلف القنوات في حساسيتها للسحب والسطح والغازات، ولذلك تقدم كل قناة منظوراً مختلفاً للغلاف الجوي."},{"type":"heading","text":"القناة المرئية"},{"type":"text","text":"تعتمد القناة المرئية أساساً على ضوء الشمس المنعكس. تظهر السحب السميكة غالباً أكثر سطوعاً من الخلفية، لكن السطوع يتأثر بزاوية الشمس وخصائص السطح وسمك السحب وقطراتها."},{"type":"heading","text":"قيود القناة المرئية"},{"type":"list","items":["لا توفر صورة مرئية تقليدية في الليل.","قد يختلط انعكاس السحب مع انعكاس الثلوج أو الرمال أو الأسطح الساطعة.","تتغير الإضاءة مع زاوية الشمس والفصل ووقت اليوم.","السطوع لا يساوي مباشرة شدة الهطول."]},{"type":"heading","text":"قناة الأشعة تحت الحمراء الحرارية"},{"type":"text","text":"تقيس القناة الحرارية الإشعاع المنبعث، ويمكن تحويله إلى درجة حرارة سطوع وفق المعايرة. تظهر قمم السحب العالية والباردة عادة بدرجات حرارة سطوع منخفضة مقارنة بالسطوح الدافئة، مع مراعاة خصائص الامتصاص والانبعاث."},{"type":"heading","text":"تفسير حرارة قمم السحب"},{"type":"text","text":"قد تشير درجات الحرارة المنخفضة جداً إلى سحب عالية أو عميقة، لكن لا تكفي وحدها لتحديد شدة العاصفة أو كمية المطر. يفيد تتبع التبريد السريع والملمس والبنية والبيانات المساندة في التفسير."},{"type":"heading","text":"قنوات بخار الماء"},{"type":"text","text":"تقع قنوات بخار الماء في نطاقات تمتص فيها جزيئات الماء الإشعاع، وتكون مساهمة الإشارة من طبقات جوية تختلف باختلاف القناة والرطوبة والحرارة. لذلك لا تمثل الصورة خريطة بسيطة لتركيز بخار الماء عند سطح الأرض."},{"type":"heading","text":"القنوات القصيرة والمتوسطة"},{"type":"text","text":"تستخدم بعض المستشعرات قنوات تحت حمراء قصيرة ومتوسطة لتمييز خصائص السحب والسطوح والحرائق أو الجليد. يجب الرجوع إلى توصيف المستشعر لأن حدود النطاقات ووظائفها تختلف بين الأقمار."},{"type":"heading","text":"التركيب اللوني RGB"},{"type":"text","text":"تجمع صور RGB ثلاث قنوات أو مشتقات في مكونات الأحمر والأخضر والأزرق لإبراز أنماط يصعب رؤيتها في قناة منفردة. يعتمد معنى الألوان على القنوات والفروق والمعالجة المختارة، وليس على لون طبيعي ثابت."},{"type":"heading","text":"أمثلة على منتجات RGB"},{"type":"list","items":["الكتل الهوائية: إبراز خصائص كتل الهواء والطبقات العليا.","الغبار: المساعدة في تمييز الغبار عن السحب في ظروف مناسبة.","العواصف الرعدية: إبراز خصائص قمم السحب والجليد.","الليل: استخدام قنوات حرارية مناسبة لتمييز السحب ليلاً."]},{"type":"heading","text":"قراءة بيانات الصورة"},{"type":"text","text":"تحقق من اسم القناة والوحدة ومقياس الألوان ووقت الالتقاط والإسقاط المكاني. في المنتجات الحرارية قد يكون المقياس درجة حرارة سطوع، بينما قد تعرض المنتجات الأخرى انعكاسية أو إشعاعاً أو قيمة مشتقة."},{"type":"callout","text":"لا تفسر اللون قبل قراءة مفتاح المنتج؛ فقد يتغير ترميز الألوان بين مزودي البيانات والمنتجات."},{"type":"example","text":"مثال: إذا ظهرت منطقة داكنة في قناة بخار الماء، فلا تستنتج مباشرة غياب الرطوبة السطحية؛ فالقناة تستجيب لإشعاع صادر من طبقات جوية ضمن نطاق امتصاص محدد."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"القنوات المرئية والحرارية وبخار الماء متكاملة. يتطلب التفسير معرفة النطاق الطيفي ومصدر الإشارة ووحدة المنتج ووقت الرصد."}]}',470,55,'["تفسير المعلومات الأساسية في القنوات المرئية وتحت الحمراء","شرح وظيفة قنوات بخار الماء","تجنب أخطاء تفسير الصور الفضائية"]','القنوات الطيفية وتفسير الصور'),
('weather-radar-reflectivity-and-radial-velocity','رادار الطقس ومبادئ الانعكاسية والسرعة الشعاعية','مبادئ عمل رادار الطقس وقراءة الانعكاسية والسرعة الشعاعية والمنتجات الأساسية وحدود الرصد.','{"blocks":[{"type":"heading","text":"مبدأ رادار الطقس"},{"type":"text","text":"يرسل رادار الطقس نبضات كهرومغناطيسية ويستقبل جزءاً من الطاقة المرتدة عن الأهداف الهيدرومطرية. يحلل النظام زمن عودة الإشارة واتجاه الهوائي وخصائصها لتقدير موقع الأهداف وشدة الإشارة المرتدة وبعض خصائص حركتها."},{"type":"heading","text":"الانعكاسية الرادارية"},{"type":"text","text":"تعبر الانعكاسية عن مقدار الطاقة المرتدة من حجم معين في الغلاف الجوي، وتتأثر بحجم القطرات وتوزيعها وتركيزها وطول موجة الرادار. تعرض غالباً بوحدة dBZ وهي مقياس لوغاريتمي."},{"type":"heading","text":"قراءة الانعكاسية"},{"type":"text","text":"تشير القيم الأعلى عموماً إلى أهداف أكثر قدرة على إرجاع الطاقة، وقد ترتبط بهطول أشد، لكن العلاقة ليست مباشرة في جميع الحالات. يتأثر التقدير بنوع الهطول وحجم القطرات والتوهين ومعايرة النظام."},{"type":"heading","text":"السرعة الشعاعية"},{"type":"text","text":"تستند السرعة الشعاعية إلى تغير تردد الإشارة المرتدة بفعل دوبلر، وتمثل مركبة حركة الهدف باتجاه الرادار أو بعيداً عنه. لا تقيس السرعة الكاملة للرياح؛ فالمركبة الموازية لحزمة الرادار لا تظهر بالطريقة نفسها."},{"type":"heading","text":"تفسير نمط الحركة"},{"type":"text","text":"يساعد توزيع السرعات الموجبة والسالبة حول الرادار على تحليل التقارب والتباعد والدوران ضمن هندسة الرصد. يعتمد التفسير على زاوية المسح والارتفاع والبيئة الجوية وخبرة المحلل، ولا يكفي لون منفرد لإثبات دوران خطير."},{"type":"heading","text":"المنتجات الرادارية الشائعة"},{"type":"list","items":["الانعكاسية الأفقية PPI.","السرعة الشعاعية.","المقطع الرأسي RHI في الأنظمة التي تدعمه.","الانعكاسية القصوى ضمن طبقة أو عمود.","تقدير الهطول المتراكم أو اللحظي من خوارزميات الرادار."]},{"type":"heading","text":"حجم الحزمة والارتفاع"},{"type":"text","text":"تتسع حزمة الرادار مع المسافة، كما يرتفع مسارها عادة بسبب انحناء الأرض وهندسة المسح. لذلك قد لا يرصد الرادار الأجزاء المنخفضة من العاصفة على المسافات البعيدة، ويجب مراعاة ارتفاع الحزمة عند تفسير الصورة."},{"type":"heading","text":"عوائق وحدود الرادار"},{"type":"list","items":["حجب الشعاع بالتضاريس أو المباني.","التوهين داخل الهطول الغزير أو على مسارات طويلة.","الأصداء الأرضية والانعكاسات غير الجوية.","الأهداف غير الجوية مثل الطيور والحشرات.","تغير جودة التغطية مع المسافة والارتفاع ونمط المسح."]},{"type":"heading","text":"تقدير الهطول"},{"type":"text","text":"تحول خوارزميات الرادار الانعكاسية إلى تقدير مطري باستخدام علاقات تجريبية أو نماذج أكثر تطوراً. تتطلب هذه التقديرات معايرة ومقارنة بمقاييس المطر، وقد تختلف الدقة باختلاف نوع الهطول والموقع."},{"type":"heading","text":"دمج الرادار مع المصادر الأخرى"},{"type":"text","text":"يستفيد المحلل من دمج الرادار مع صور الأقمار الصناعية ومحطات المطر والبرق والملاحظات السطحية والنماذج العددية. يساهم الدمج في التحقق من امتداد الهطول وتطوره ونوعه."},{"type":"callout","text":"الانعكاسية ليست كمية مطر مباشرة، والسرعة الشعاعية ليست متجه الرياح الكامل؛ اقرأ كل منتج وفق ما يقيسه فعلياً."},{"type":"example","text":"مثال: عند مشاهدة انعكاسية مرتفعة، افحص الاستمرارية الرأسية والسرعة الشعاعية ومقاييس المطر ووجود التوهين أو الأصداء الأرضية قبل إصدار تقدير للهطول."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يوفر الرادار تفاصيل مكانية وزمنية مهمة للهطول والحركة، لكن تفسيره يتطلب فهم الانعكاسية والسرعة الشعاعية وهندسة الحزمة ومصادر الخطأ."}]}',480,55,'["شرح مبدأ رادار الطقس بصورة مفاهيمية","التمييز بين الانعكاسية والسرعة الشعاعية","تفسير المنتجات الرادارية مع مراعاة القيود"]','رادار الطقس ومنتجاته'),
('satellite-and-radar-imagery-synoptic-analysis','تفسير صور الأقمار الصناعية ومنتجات الرادار في التحليل الجوي','منهج دمج الصور الفضائية والمنتجات الرادارية والرصد السطحي في تشخيص الأنظمة الجوية ومتابعتها.','{"blocks":[{"type":"heading","text":"من الصورة إلى التشخيص الجوي"},{"type":"text","text":"يتطلب التحليل الجوي الانتقال من وصف ما يظهر في الصورة إلى تفسير فيزيائي مدعوم بمصادر مستقلة. يبدأ المحلل بتحديد وقت الصورة والقناة والمنتج وجودته، ثم يدرس الأنماط والتطور الزمني ويقارنها بالخرائط والقياسات."},{"type":"heading","text":"التحقق من البيانات الوصفية"},{"type":"list","items":["اسم القمر والمستشعر والقناة أو المنتج.","وقت الالتقاط ووقت المعالجة والمنطقة الزمنية.","الإسقاط المكاني والدقة ومقياس الألوان.","حالة الجودة وأي فجوات أو تشوهات في الصورة."]},{"type":"heading","text":"تحليل السحب في الصور المرئية"},{"type":"text","text":"تساعد الصور المرئية في وصف التوزيع والملمس والامتداد والظلال خلال النهار. يمكن تتبع خطوط السحب والخلايا الحملية والأشرطة السحابية، مع تجنب استنتاج نوع السحب من السطوع وحده."},{"type":"heading","text":"تحليل السحب في تحت الحمراء"},{"type":"text","text":"تستخدم درجات حرارة السطوع لتقدير برودة قمم السحب وارتفاعها المحتمل عند توفر معلومات حرارية مناسبة. يفيد تتبع مناطق التبريد السريع والقمم الباردة في رصد نمو الحمل العميق، لكن يلزم التحقق بمنتجات أخرى."},{"type":"heading","text":"تحليل قنوات بخار الماء"},{"type":"text","text":"تظهر قنوات بخار الماء أنماطاً مرتبطة بالرطوبة والحركة في طبقات جوية عليا ومتوسطة وفق نطاق القناة. يمكن أن تساعد في تتبع الأخاديد والنتوءات الجافة وتيارات الهواء، لكنها ليست قياساً مباشراً لرطوبة سطح الأرض."},{"type":"heading","text":"التحليل الراداري للهطول"},{"type":"text","text":"توضح خرائط الانعكاسية توزيع الأهداف الهيدرومطرية وشدتها النسبية، بينما تساعد السرعة الشعاعية على تقييم مكونات الحركة باتجاه الرادار أو بعيداً عنه. تتابع الصور المتعاقبة حركة الخلايا وتطورها."},{"type":"heading","text":"تمييز الأنظمة الجوية"},{"type":"list","items":["الجبهات: ابحث عن أحزمة سحابية ممتدة وتغيرات متزامنة في الضغط والرياح والحرارة.","الحمل الحراري: راقب نمو الخلايا وتطور قممها والانعكاسية الرادارية.","المنخفضات: ادمج دوران السحب مع خرائط الضغط والرياح والارتفاعات.","الغبار: قارن القنوات الطيفية والرياح السطحية والرؤية الأفقية."]},{"type":"heading","text":"التطور الزمني"},{"type":"text","text":"لا تكفي لقطة منفردة لفهم النظام الجوي. قارن سلسلة زمنية مع مراعاة الفاصل بين الصور وتغير زاوية الشمس وجدول المسح، وحدد مناطق النمو والتلاشي والحركة."},{"type":"heading","text":"دمج المصادر"},{"type":"text","text":"اجمع صور الأقمار والرادار مع محطات الرصد والبالونات والنماذج العددية وتقارير الطيران والبحر عند توافرها. لكل مصدر دقة ومجال وزمن مختلف، ولذلك يجب توحيد التوقيت والمقارنة على مقياس مكاني مناسب."},{"type":"heading","text":"بناء استنتاج قابل للمراجعة"},{"type":"list","items":["صف السمة المرصودة دون تفسير أولي.","حدد المنتج وما يقيسه فعلياً.","اقترح تفسيراً جوياً مع بدائل ممكنة.","اختبر التفسير بمصادر مستقلة.","سجل مستوى الثقة والقيود والبيانات الناقصة."]},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار اللون دليلاً ثابتاً دون مفتاح المنتج.","استنتاج الهطول من قناة فضائية واحدة.","قراءة السرعة الشعاعية كأنها سرعة الرياح الكاملة.","إهمال ارتفاع حزمة الرادار والتضاريس.","مقارنة صور مختلفة التوقيت أو الدقة دون مواءمة."]},{"type":"callout","text":"التحليل الاحترافي يميز بين الملاحظة والتفسير والاستنتاج، ويذكر مستوى الثقة والقيود بدلاً من تقديم الصورة كدليل قطعي."},{"type":"example","text":"مثال تطبيقي: تتبع خلية رعدية باستخدام تسلسل تحت الحمراء لتطور القمة، والانعكاسية لموقع الهطول، والسرعة الشعاعية للحركة باتجاه الرادار أو بعيداً عنه، ثم تحقق من المحطات والبرق."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"أفضل تحليل جوي هو تحليل متعدد المصادر والزمن، يربط كل منتج بما يقيسه ويختبر الاستنتاجات ويحتفظ بسجل واضح للأدلة والقيود."}]}',490,60,'["اتباع تسلسل منظم لتحليل الصور الفضائية والرادارية","ربط السمات المرئية بالأنظمة الجوية المحتملة","دمج مصادر الرصد مع توثيق حدود الاستنتاج"]','التحليل الجوي بالاستشعار عن بعد')
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,
case d.unit when 'أساسيات الاستشعار عن بعد' then u1.id when 'أنواع الأقمار الصناعية ومداراتها' then u2.id when 'القنوات الطيفية وتفسير الصور' then u3.id when 'رادار الطقس ومنتجاته' then u4.id else u5.id end,
d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'الاستشعار عن بعد والأقمار الصناعية والرادار',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;